return {["scripts/actions/weaponskills/tachi_fudo.lua"]={["Path"]="scripts/actions/weaponskills/tachi_fudo.lua",["SHA256"]="0b06857fe8e99b06a1cd55a94fb62668167489ed949e2d852b61305cabe51001",["Text"]="-----------------------------------\n-- Tachi: Fudo\n-- Great Katana weapon skill\n-- Skill Level: N/A\n-- Deals double damage. Damage varies with TP. Masamune: Aftermath.\n-- Available only when equipped with Masamune (85), Masamune (90), Masamune (95), Hiradennotachi +1 or Hiradennotachi +2.\n-- Aligned with Light Gorget, Snow Gorget & Aqua Gorget.\n-- Aligned with Light Belt, Snow Belt & Aqua Belt.\n-- Element: None\n-- Modifiers: STR:80%\n-- 100%TP    200%TP    300%TP\n-- 3.75      5.75        8\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 3.75, 4.75, 5.75 }\n    params.str_wsc = 0.60\n    params.atkVaries = { 2.0, 2.0, 2.0 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 3.75, 5.75, 8.0 }\n        params.str_wsc = 0.8\n        params.atkVaries = { 1.0, 1.0, 1.0 }\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.EMPYREAN)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/tachi_gekko.lua"]={["Path"]="scripts/actions/weaponskills/tachi_gekko.lua",["SHA256"]="bd36096b4e8aaabab82a8c464b2a3bb140e6b1f7b69eb6150434c3ca97cb2916",["Text"]="-----------------------------------\n-- Tachi Gekko\n-- Great Katana weapon skill\n-- Skill Level: 225\n-- Silences target. Damage varies with TP.\n-- Silence effect duration is 60 seconds when unresisted.\n-- Will stack with Sneak Attack.\n-- Tachi: Gekko has a high attack bonus of +100%. [1]\n-- Aligned with the Aqua Gorget & Snow Gorget.\n-- Aligned with the Aqua Belt & Snow Belt.\n-- Element: None\n-- Modifiers: STR:75%\n-- 100%TP    200%TP    300%TP\n-- 1.5625      2.6875      4.125\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params     = {}\n    params.numHits   = 1\n    params.ftpMod    = { 1.5625, 1.88, 2.5 }\n    params.str_wsc   = 0.75\n    params.atkVaries = { 2, 2, 2 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 1.5625, 2.6875, 4.125 }\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.SILENCE\n    local actionElement = xi.element.WIND\n    local power         = 1\n    local duration      = math.floor(45 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/tachi_goten.lua"]={["Path"]="scripts/actions/weaponskills/tachi_goten.lua",["SHA256"]="875c88e8442f20114e04adeee0c94f35087931c16705bb7348955451e27ed3f2",["Text"]="-- ---------------------------------\n-- Tachi Goten\n-- Great Katana weapon skill\n-- Skill Level: 70\n-- Deals lightning elemental damage to enemy. Damage varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Light Gorget / Thunder Gorget.\n-- Aligned with the Light Belt / Thunder Belt.\n-- Element: Thunder\n-- Modifiers: STR:60%\n-- 100%TP    200%TP    300%TP\n-- .5         .75      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.3\n    params.hybridWS = true\n    params.ele = xi.element.THUNDER\n    params.skill = xi.skill.GREAT_KATANA\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 0.5, 1.5, 2.5 }\n        params.str_wsc = 0.6\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/tachi_hobaku.lua"]={["Path"]="scripts/actions/weaponskills/tachi_hobaku.lua",["SHA256"]="d5ca23b67494f027452e11c5eddb4c6d3114c8db71f583cbcd4d185a67895833",["Text"]="-----------------------------------\n-- Tachi Hobaku\n-- Great Katana weapon skill\n-- Skill Level: 30\n-- Stuns enemy. Chance of stun varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Snow Gorget.\n-- Aligned with the Snow Belt.\n-- Element: None\n-- Modifiers: STR:60%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1, 1, 1 }\n    params.str_wsc = 0.3\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.6\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    if math.randomInt(1, 100) <= tp / 30 * applyResistanceAddEffect(player, target, xi.element.THUNDER, 0) then\n        local effectId      = xi.effect.STUN\n        local actionElement = xi.element.THUNDER\n        local power         = 1\n        local duration      = 3\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/tachi_jinpu.lua"]={["Path"]="scripts/actions/weaponskills/tachi_jinpu.lua",["SHA256"]="443a40f773b3a50ec88abfe2113fbfe79ae174edb24d26a234c62ea40e32041a",["Text"]="-----------------------------------\n-- Tachi Jinpu\n-- Great Katana weapon skill\n-- Skill level: 150\n-- Two-hit attack. Deals Physical and wind elemental damage to enemy. Additonal Effect Damage varies with TP.\n-- Will stack with Sneak Attack and Souleater.\n-- Aligned with the Breeze Gorget & Shadow Gorget.\n-- Aligned with the Breeze Belt & Shadow Belt.\n-- Element: Wind\n-- Modifiers: STR:30%\n-- 100%TP    200%TP    300%TP\n-- .5         .75      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 2\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.4\n    params.hybridWS = true\n    params.includemab = true\n    params.ele = xi.element.WIND\n    params.skill = xi.skill.GREAT_KATANA\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 0.5, 1.5, 2.5 }\n        params.str_wsc = 0.3\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/tachi_kagero.lua"]={["Path"]="scripts/actions/weaponskills/tachi_kagero.lua",["SHA256"]="9b2a60999446cf2f2dca95610b701a3708e0a3fbd706bcf3404690603b0b668e",["Text"]="-----------------------------------\n-- Tachi Kagero\n-- Great Katana weapon skill\n-- Skill Level: 100\n-- Deals fire elemental damage to enemy. Damage varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Flame Gorget.\n-- Aligned with the Flame Belt.\n-- Element: Fire\n-- Modifiers: STR:75%\n-- 100%TP    200%TP    300%TP\n-- .5        .75       1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.5\n    params.hybridWS = true\n    params.ele = xi.element.FIRE\n    params.skill = xi.skill.GREAT_KATANA\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 0.5, 1.5, 2.5 }\n        params.str_wsc = 0.75\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/tachi_kaiten.lua"]={["Path"]="scripts/actions/weaponskills/tachi_kaiten.lua",["SHA256"]="26f3f7ce8228caf6541de667763b359d222bae51f3327ca424d04c7daa57f219",["Text"]="-----------------------------------\n-- Tachi Kaiten\n-- Great Katana weapon skill\n-- Skill level: N/A\n-- Additional effect: temporarily increases amount of TP stored with each hit.\n-- Grants Store TP+7 for the duration of time that it is active. Length of time depends on TP.\n-- 100 TP = 20s\n-- 200 TP = 40s\n-- 300 TP = 60s\n-- This weapon skill is only available with the stage 5 relic Great Katana Amanomurakumo or within Dynamis with the stage 4 Totsukanotsurugi.\n-- Also available as a Latent effect on Ame-no-ohabari\n-- Aligned with the Breeze Gorget, Thunder Gorget & Light Gorget.\n-- Aligned with the Breeze Belt, Thunder Belt & Light Belt.\n-- Element: None\n-- Modifiers: STR:75%\n-- 100%TP    200%TP    300%TP\n-- 3.00      3.00      3.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 3.0, 3.0, 3.0 }\n    params.str_wsc = 0.6\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.8\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.RELIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/tachi_kasha.lua"]={["Path"]="scripts/actions/weaponskills/tachi_kasha.lua",["SHA256"]="52ee4fd76cea2864d9e353568dba7b231e2f641dcd7c3acad288ddc27dfb9261",["Text"]="-----------------------------------\n-- Tachi Kasha\n-- Great Katana weapon skill\n-- Skill Level: 250\n-- Paralyzes target. Damage varies with TP.\n-- Paralyze effect duration is 60 seconds when unresisted.\n-- In order to obtain Tachi: Kasha, the quest The Potential Within must be completed.\n-- Will stack with Sneak Attack.\n-- Tachi: Kasha appears to have a moderate attack bonus of +50%. [1]\n-- Aligned with the Flame Gorget, Light Gorget & Shadow Gorget.\n-- Aligned with the Flame Belt, Light Belt & Shadow Belt.\n-- Element: None\n-- Modifiers: STR:75%\n-- 100%TP    200%TP    300%TP\n-- 1.5625    2.6875    4.125\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params     = {}\n    params.numHits   = 1\n    params.ftpMod    = { 1.56, 1.88, 2.5 }\n    params.str_wsc   = 0.75\n    params.atkVaries = { 1.5, 1.5, 1.5 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod    = { 1.5625, 2.6875, 4.125 }\n        params.str_wsc   = 0.75\n        params.atkVaries = { 1.65, 1.65, 1.65 }\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.PARALYSIS\n    local actionElement = xi.element.ICE\n    local power         = 25\n    local duration      = math.floor(60 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/tachi_koki.lua"]={["Path"]="scripts/actions/weaponskills/tachi_koki.lua",["SHA256"]="881d40df6dd366c4340659dc78ad7dcea65b0aecf3d9fa0f84576b509a481544",["Text"]="-----------------------------------\n-- Tachi Koki\n-- Great Katana weapon skill\n-- Skill level: 175\n-- Deals light elemental damage to enemy. Damage varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Aqua Gorget & Thunder Gorget.\n-- Aligned with the Aqua Belt & Thunder Belt.\n-- Element: Light\n-- Modifiers: STR:30%  MND:50%\n-- 100%TP    200%TP    300%TP\n-- .5        .75        1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 0.5, 0.75, 1.0 }\n    params.str_wsc = 0.5 params.mnd_wsc = 0.3\n    params.hybridWS = true\n    params.ele = xi.element.LIGHT\n    params.skill = xi.skill.GREAT_KATANA\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 0.5, 1.5, 2.5 }\n        params.str_wsc = 0.3 params.mnd_wsc = 0.5\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/tachi_rana.lua"]={["Path"]="scripts/actions/weaponskills/tachi_rana.lua",["SHA256"]="8fd90c2905ca4238a0dacf7a55198427353a211480f08b5edc3aa979187c5b76",["Text"]="-----------------------------------\n-- Tachi Rana\n-- Great Katana weapon skill\n-- Skill Level: N/A\n-- Delivers a three-fold attack. params.accuracy varies with TP. Aftermath effect varies with TP. See Kogarasumaru.\n-- In order to obtain Tachi: Rana, the Unlocking a Myth (Samurai) quest must be completed.\n-- Will stack with Sneak Attack (first hit only).\n-- Aligned with the Shadow Gorget, Soil Gorget & Snow Gorget.\n-- Aligned with the Shadow Belt, Soil Belt & Snow Belt.\n-- Element: None\n-- Modifiers: STR:35%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 3\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.35\n    params.accVaries = { 0, 30, 60 } -- TODO: verify exact number\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.5\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/tachi_shoha.lua"]={["Path"]="scripts/actions/weaponskills/tachi_shoha.lua",["SHA256"]="e5d86f9370edd9605014516126163e79f09e502a30d566b2cd9bfe467685c7fe",["Text"]="-----------------------------------\n-- Tachi: Shoha\n-- Great Katana weapon skill\n-- Skill Level: 357\n-- Delivers a two-hit attack. Damage varies with TP.\n-- To obtain Tachi: Shoha, the quest Martial Mastery must be completed and it must be purchased from the Merit Points menu.\n-- Suspected to have an Attack Bonus similar to Tachi: Yukikaze, Tachi: Gekko, and Tachi: Kasha, but only on the first hit.\n-- Aligned with the Breeze Gorget, Thunder Gorget & Shadow Gorget.\n-- Aligned with the Breeze Belt, Thunder Belt & Shadow Belt.\n-- Element: None\n-- Modifiers: STR:73~85%, depending on merit points upgrades.\n-- 100%TP    200%TP    300%TP\n-- 1.375     2.1875      2.6875\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 2\n    params.ftpMod = { 1.375, 2.1875, 2.6875 }\n    params.str_wsc = player:getMerit(xi.merit.TACHI_SHOHA) * 0.17\n    params.atkVaries = { 1.375, 1.375, 1.375 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.7 + (player:getMerit(xi.merit.TACHI_SHOHA) * 0.03)\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/tachi_suikawari.lua"]={["Path"]="scripts/actions/weaponskills/tachi_suikawari.lua",["SHA256"]="f332d094c59cc01afa1f7b12378ac9080ac499e07882a4cee21aba5cb5e136cf",["Text"]="-----------------------------------\n-- Tachi Suikawari\n-- Great Katana weapon skill\n-- Is the joke variant of Tachi: Kaiten, using the same animation.\n-- Skill level: N/A Only usable when equipping Melon Slicer\n-- Number of watermelons sliced varies with TP.\n-- Element: Fusion\n-- Modifiers: STR:80% (Using Tachi: Kaiten as it is based on that WS)\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.50      2.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 2\n    params.ftpMod = { 1.0, 1.5, 2.0 }\n    params.str_wsc = 0.6\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.8\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/tachi_yukikaze.lua"]={["Path"]="scripts/actions/weaponskills/tachi_yukikaze.lua",["SHA256"]="c19be50626772ed680e9654d9375f118c17c9c6f0015beffa3bd200aab9fb1d8",["Text"]="-----------------------------------\n-- Tachi Yukikaze\n-- Great Katana weapon skill\n-- Skill Level: 200 (Samurai only.)\n-- Blinds target. Damage varies with TP.\n-- Blind effect duration is 60 seconds when unresisted.\n-- Will stack with Sneak Attack.\n-- Tachi: Yukikaze appears to have an attack bonus of 50%. http://www.bg-wiki.com/bg/Tachi:_Yukikaze\n-- Aligned with the Snow Gorget & Breeze Gorget.\n-- Aligned with the Snow Belt & Breeze Belt.\n-- Element: None\n-- Modifiers: STR:75%\n-- 100%TP    200%TP    300%TP\n-- 1.5625    2.6875    4.125\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params     = {}\n    params.numHits   = 1\n    params.ftpMod    = { 1.5625, 1.88, 2.5 }\n    params.str_wsc   = 0.75\n    params.atkVaries = { 1.33, 1.33, 1.33 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod    = { 1.5625, 2.6875, 4.125 }\n        params.atkVaries = { 1.5, 1.5, 1.5 }\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.BLINDNESS\n    local actionElement = xi.element.DARK\n    local power         = 25\n    local duration      = math.floor(60 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/thunder_thrust.lua"]={["Path"]="scripts/actions/weaponskills/thunder_thrust.lua",["SHA256"]="776b30180b5e7275da1b2320bcb4a57a0ec2f5f3c736ad40be886c87cd2264b3",["Text"]="-----------------------------------\n-- Thunder Thrust\n-- Polearm weapon skill\n-- Skill Level: 30\n-- Deals lightning elemental damage to enemy. Damage varies with TP.\n-- Aligned with the Light Gorget & Thunder Gorget.\n-- Aligned with the Light Belt & Thunder Belt.\n-- Element: Lightning\n-- Modifiers: STR:40%  INT:40%\n-- 100%TP    200%TP    300%TP\n-- 1.50      2.00      2.50\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 1.5, 2.0, 2.5 }\n    params.str_wsc = 0.2 params.int_wsc = 0.2\n    params.ele = xi.element.THUNDER\n    params.skill = xi.skill.POLEARM\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.4 params.int_wsc = 0.4\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/torcleaver.lua"]={["Path"]="scripts/actions/weaponskills/torcleaver.lua",["SHA256"]="b5b3f18387b8b4c205e3b1b60eb3ccb254650bd589d624a54af391168ba4c6dd",["Text"]="-----------------------------------\n-- Torcleaver\n-- Skill Level: N/A\n-- Description: Deals triple damage. Damage varies with TP. Caladbolg: Aftermath.\n-- Available only when equipped with Caladbolg (85)/(90)/(95) or Espafut +1/+2/+3.\n-- Aligned with the Light Gorget, Aqua Gorget & Snow Gorget.\n-- Aligned with the Light Belt, Aqua Belt & Snow Belt.\n-- Element: None\n-- Skillchain Properties: Light/Distortion\n-- Modifiers: VIT:60%\n-- Damage Multipliers by TP:\n-- 100%TP    200%TP    300%TP\n-- 4.75        5.75    6.5\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 4.75, 5.75, 6.5 }\n    params.vit_wsc = 0.6\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 4.75, 7.5, 10.0 }\n        params.vit_wsc = 0.8\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.EMPYREAN)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/tornado_kick.lua"]={["Path"]="scripts/actions/weaponskills/tornado_kick.lua",["SHA256"]="2e72f2fc47f24be03482e787ff6b9a1e5a78786d996eb213f6d4ca1fb94d07dd",["Text"]="-----------------------------------\n-- Skill: Tornado Kick\n-- Class: H2H Weapon Skill\n-- Level: 225\n-- Mods : STR:32% VIT:32%\n-- 100%TP     200%TP     300%TP\n-- 2.25x        2.75x    3.5x\n-- Delivers a threefold attack. Damage varies with TP.\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    -- number of normal hits for ws\n    params.numHits = 3\n    -- stat-modifiers (0.0 = 0%, 0.2 = 20%, 0.5 = 50%..etc)\n    params.str_wsc = 0.32\n    params.vit_wsc = 0.32\n\n    params.ftpMod = { 2.25, 2.75, 3.5 }\n    params.kick = true -- https://www.bluegartr.com/threads/112776-Dev-Tracker-Findings-Posts-%28NO-DISCUSSION%29?p=6712150&viewfull=1#post6712150\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 1.7, 2.8, 4.5 }\n        params.str_wsc = 0.4 params.vit_wsc = 0.4\n        params.multiHitfTP = true -- http://wiki.ffo.jp/html/20199.html\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/true_strike.lua"]={["Path"]="scripts/actions/weaponskills/true_strike.lua",["SHA256"]="4f2a2bc1802b89b578d7d6dcfa84ee929dfbac5e6489cf69c4dcbe755504f865",["Text"]="-----------------------------------\n-- True Strike\n-- Club weapon skill\n-- Skill level: 175\n-- Deals params.critical damage. params.accuracy varies with TP.\n-- 100% Critical Hit Rate. Has a substantial accuracy penalty at 100TP. http://www.bg-wiki.com/bg/True_Strike\n-- Will stack with Sneak Attack.\n-- Aligned with the Breeze Gorget & Thunder Gorget.\n-- Aligned with the Breeze Belt & Thunder Belt.\n-- Element: None\n-- Modifiers: STR:100%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.5\n    params.critVaries = { 1.0, 1.0, 1.0 }\n    params.accVaries = { -50, -50, -50 } -- TODO: verify exact number.\n    params.atkVaries  = { 2.0, 2.0, 2.0 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 1.0\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/trueflight.lua"]={["Path"]="scripts/actions/weaponskills/trueflight.lua",["SHA256"]="8f21c0beba2d0a92d31cd9382c40fee8bb70d62748aa744fcabc8c8746bda6eb",["Text"]="-----------------------------------\n-- Trueflight\n-- Skill Level: N/A\n-- Description: Deals light elemental damage. Damage varies with TP. Gastraphetes: Aftermath effect varies with TP.\n-- Available only after completing the Unlocking a Myth (Ranger) quest.\n-- Does not work with Flashy Shot.\n-- Does not work with Stealth Shot.\n-- Aligned with the Breeze Gorget, Thunder Gorget & Soil Gorget.\n-- Aligned with the Breeze Belt, Thunder Belt & Soil Belt.\n-- Properties\n-- Element: Light\n-- Skillchain Properties: Fragmentation/Scission\n-- Modifiers: AGI:30%\n-- Damage Multipliers by TP:\n--  100%TP    200%TP    300%TP\n--   4.0    4.25    4.75\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 4.0, 4.25, 4.75 }\n    params.agi_wsc = 0.3\n    params.ele = xi.element.LIGHT\n    params.skill = xi.skill.MARKSMANSHIP\n    params.includemab = true\n    params.dStat = xi.mod.AGI\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 3.8906, 6.3906, 9.3906 }\n        params.agi_wsc = 1.0\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.RANGED, xi.aftermath.type.MYTHIC)\n\n    local damage, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n\n    return tpHits, extraHits, false, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/ukkos_fury.lua"]={["Path"]="scripts/actions/weaponskills/ukkos_fury.lua",["SHA256"]="669601be5af7dda7784d671542abed48baeb4d7b248417046c1b9a75ff7c7815",["Text"]="-----------------------------------\n-- Ukko's Fury\n-- Great Axe Weapon Skill\n-- Skill Level: N/A\n-- Description: Delivers a twofold attack that slows target. Chance of params.critical hit varies with TP. Ukonvasara: Aftermath.\n-- Available only when equipped with Ukonvasara (85), Ukonvasara (90), Ukonvasara (95), Maschu +1, Maschu +2.\n-- Aligned with the Light Gorget, Breeze Gorget & Thunder Gorget.\n-- Aligned with the Light Belt, Breeze Belt & Thunder Belt.\n-- Element: None\n-- Skillchain Properties: Light/Fragmentation\n-- Modifiers: STR:80%\n-- Damage Multipliers by TP:\n-- 100%TP    200%TP    300%TP\n-- 2.0        2.0        2.0\n-- params.critical Chance added with TP:\n-- 100%TP    200%TP    300%TP\n-- 20%        35%        55%\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.numHits    = 2\n    params.ftpMod     = { 2, 2, 2 }\n    params.str_wsc    = 0.6\n    params.critVaries = { 0.2, 0.35, 0.55 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.8\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.EMPYREAN)\n\n    -- Handle status effect\n    local effectId      = xi.effect.SLOW\n    local actionElement = xi.element.EARTH\n    local power         = 1500\n    local duration      = math.floor(60 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/upheaval.lua"]={["Path"]="scripts/actions/weaponskills/upheaval.lua",["SHA256"]="aac9328e1ffcc05a854a7b73d6b25e7a0191cc760b006dbee7892a0ff768a29f",["Text"]="-----------------------------------\n-- Upheaval\n-- Great Axe weapon skill\n-- Skill Level: 357\n-- Delivers a four-hit attack. Damage varies with TP.\n-- In order to obtain Upheaval, the quest Martial Mastery must be completed.\n-- Aligned with Flame Gorget, Light Gorget & Shadow Gorget.\n-- Aligned with Flame Belt, Light Belt & Shadow Belt.\n-- Element: None\n-- Modifiers: VIT: 73~85%, depending on merit points upgrades.\n-- 100%TP    200%TP    300%TP\n-- 1.00        3.50       6.5\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 4\n    params.ftpMod = { 1.0, 3.5, 6.5 }\n    params.vit_wsc = player:getMerit(xi.merit.UPHEAVAL) * 0.17\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.vit_wsc = 0.7 + (player:getMerit(xi.merit.UPHEAVAL) * 0.03)\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/uriel_blade.lua"]={["Path"]="scripts/actions/weaponskills/uriel_blade.lua",["SHA256"]="5e27f51c3a82b0b3f29fb25e76366aadaf84ac4bd1317445ff269b2a3618038b",["Text"]="-----------------------------------\n-- Uriel Blade\n-- Sword weapon skill\n-- Skill Level: N/A\n-- Description: Delivers an area attack that deals light elemental damage. Damage varies with TP. Additional effect Flash.\n-- AoE range ??.\n-- Only available during Campaign Battle while wielding a Griffinclaw.\n-- Aligned with the Thunder Gorget & Breeze Gorget.\n-- Aligned with Thunder Belt & Breeze Belt.\n-- Modifiers: STR: 32% MND:32%\n-- 100%TP    200%TP    300%TP\n-- 4.50      6.00      7.50\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 4.5, 6, 7.5 }\n    params.str_wsc    = 0.32\n    params.mnd_wsc    = 0.32\n    params.ele        = xi.element.LIGHT\n    params.skill      = xi.skill.SWORD\n    params.includemab = true\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n\n    -- Handle status effect\n    local effectId      = xi.effect.FLASH\n    local actionElement = xi.element.LIGHT\n    local power         = 200\n    local duration      = math.floor(15 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/victory_smite.lua"]={["Path"]="scripts/actions/weaponskills/victory_smite.lua",["SHA256"]="dc78a63ce68ab9e63bbf8558a8538bd8b72403402687eec07e2f5db80aeb702f",["Text"]="-----------------------------------\n-- Victory Smite\n-- Hand-to-Hand Weapon Skill\n-- Skill Level: N/A\n-- Description: Delivers a fourfold attack. Chance of params.critical hit varies with TP.\n-- Must have Verethragna (85)/(90)/(95)/(99)/(99-2) or Revenant Fists +1/+2/+3 equipped.\n-- Aligned with the Light Gorget, Breeze Gorget & Thunder Gorget.\n-- Aligned with the Light Belt, Breeze Belt & Thunder Belt.\n-- Element: None\n-- Skillchain Properties: Light, Fragmentation\n-- Modifiers: STR:60%\n-- Damage Multipliers by TP:\n-- 100%TP    200%TP    300%TP\n-- 2.25        2.25    2.25\n-- params.critical Chance added with TP:\n-- 100%TP    200%TP    300%TP\n-- 10%        25%        45%\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 4\n    params.ftpMod = { 2.25, 2.25, 2.25 }\n    params.str_wsc = 0.6\n    params.critVaries = { 0.1, 0.25, 0.45 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.multiHitfTP = true -- http://wiki.ffo.jp/html/21093.html\n        params.ftpMod = { 1.5, 1.5, 1.5 }\n        params.str_wsc = 0.8\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.EMPYREAN)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/vidohunir.lua"]={["Path"]="scripts/actions/weaponskills/vidohunir.lua",["SHA256"]="05561c07a98aae9fa798f008916ec8dfe18f7f4d8de2d5e1d13277e76da57266",["Text"]="-----------------------------------\n-- Vidohunir\n-- Staff weapon skill\n-- Skill Level: N/A\n-- Lowers target's magic defense. Duration of effect varies with TP. Laevateinn: Aftermath effect varies with TP.\n-- Reduces enemy's magic defense by 10%.\n-- Available only after completing the Unlocking a Myth (Black Mage) quest.\n-- Aligned with the Breeze Gorget, Thunder Gorget, Aqua Gorget & Snow Gorget.\n-- Aligned with the Breeze Belt, Thunder Belt, Aqua Belt & Snow Belt.\n-- Element: Darkness\n-- Modifiers: INT:30%\n-- 100%TP    200%TP    300%TP\n-- 1.75      1.75      1.75\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 1.75, 1.75, 1.75 }\n    params.int_wsc    = 0.3\n    params.ele        = xi.element.DARK\n    params.skill      = xi.skill.STAFF\n    params.includemab = true\n    -- params.dStat = xi.mod.INT (pINT-mINT)×2 (Not supported in weaponskills.lua currently)\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.int_wsc = 0.8\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n\n    -- Handle status effect\n    local effectId      = xi.effect.MAGIC_DEF_DOWN\n    local actionElement = xi.element.THUNDER\n    local power         = 10\n    local duration      = math.floor(6 * tp / 100 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/viper_bite.lua"]={["Path"]="scripts/actions/weaponskills/viper_bite.lua",["SHA256"]="a4318f14d6e41bbbd4b581e4413da7962a4da280793f5bf646e743eea880c7d9",["Text"]="-----------------------------------\n-- Viper Bite\n-- Dagger weapon skill\n-- Skill level: 100\n-- Deals double damage and Poisons target. Duration of poison varies with TP.\n-- Doubles attack and not damage.\n-- Despite the animation showing two swings, this is a single-hit weapon skill.\n-- Will stack with Sneak Attack.\n-- Aligned with the Soil Gorget.\n-- Aligned with the Soil Belt.\n-- Element: None\n-- Modifiers: :\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params     = {}\n    params.numHits   = 1\n    params.ftpMod    = { 1, 1, 1 }\n    params.atkVaries = { 2, 2, 2 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.dex_wsc = 1\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.POISON\n    local actionElement = xi.element.WATER\n    local power         = 3\n    local duration      = math.floor((30 + 6 * tp / 100) * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/vorpal_blade.lua"]={["Path"]="scripts/actions/weaponskills/vorpal_blade.lua",["SHA256"]="fe36cfc217378c0966c901f8b4cfae15004461885259528bbeb53e449f5bb975",["Text"]="-----------------------------------\n-- Vorpal Blade\n-- Sword weapon skill\n-- Skill Level: 200\n-- Delivers a four-hit attack. Chance of params.critical varies with TP.\n-- Stacks with Sneak Attack.\n-- Aligned with the Soil Gorget & Thunder Gorget.\n-- Aligned with the Soil Belt & Thunder Belt.\n-- Element: None\n-- Modifiers: STR:60%\n-- 100%TP    200%TP    300%TP\n-- 1.375      1.375      1.375\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 4\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.3\n    params.critVaries = { 0.1, 0.3, 0.5 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 1.375, 1.375, 1.375 }\n        params.str_wsc = 0.6\n        params.multiHitfTP = true\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/vorpal_scythe.lua"]={["Path"]="scripts/actions/weaponskills/vorpal_scythe.lua",["SHA256"]="34357a5be3ca7a884d979cb774832f132b1244b514f2f59c6ec97c4e997933c3",["Text"]="-----------------------------------\n-- Vorpal Scythe\n-- Scythe weapon skill\n-- Skill level: 150\n-- Delivers a single-hit attack. params.crit varies with TP.\n-- Modifiers: STR:100%\n-- 100%TP     200%TP     300%TP\n-- 1.0         1.0        1.0\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    -- wscs are in % so 0.2=20%\n    params.str_wsc = 0.35\n    params.critVaries = { 0.3, 0.6, 0.9 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 1.0\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/vorpal_thrust.lua"]={["Path"]="scripts/actions/weaponskills/vorpal_thrust.lua",["SHA256"]="1450453a619da067ca773181220949484fb2e38e1108b451451dd9b6e52032a5",["Text"]="-----------------------------------\n-- Vorpal Thrust\n-- Polearm weapon skill\n-- Skill Level: 175\n-- Delivers a single-hit attack. Chance of params.critical varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Aqua Gorget & Light Gorget.\n-- Aligned with the Aqua Belt & Light Belt.\n-- Element: None\n-- Modifiers: STR:50%  AGI:50%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.2 params.agi_wsc = 0.2\n    params.critVaries = { 0.3, 0.6, 0.9 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.5 params.agi_wsc = 0.5\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/wasp_sting.lua"]={["Path"]="scripts/actions/weaponskills/wasp_sting.lua",["SHA256"]="80486b493a2e86d4960876156ef4520d5bc4aed876148126dcfc3453df984a42",["Text"]="-----------------------------------\n-- Wasp Sting\n-- Dagger weapon skill\n-- Skill level: 5\n-- Poisons target. Duration of effect varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Soil Gorget.\n-- Aligned with the Soil Belt.\n-- Element: None\n-- Modifiers: :    DEX:100%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1, 1, 1 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.dex_wsc = 1\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.POISON\n    local actionElement = xi.element.WATER\n    local power         = 1\n    local duration      = math.floor((75 + 15 * tp / 1000) * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/weapon_break.lua"]={["Path"]="scripts/actions/weaponskills/weapon_break.lua",["SHA256"]="bd550e5711dd67e4f9b19670297f08650eef1c15bb5a4aba7d1326bd5383da30",["Text"]="-----------------------------------\n-- Weapon Break\n-- Great Axe weapon skill\n-- Skill level: 175\n-- Lowers enemy's attack. Duration of effect varies with TP.\n-- Lowers attack by as much as 25% if unresisted.\n-- Strong against: Manticores, Orcs, Rabbits, Raptors, Sheep.\n-- Immune: Crabs, Crawlers, Funguars, Quadavs, Pugils, Sahagin, Scorpion.\n-- Will stack with Sneak Attack.\n-- Aligned with the Thunder Gorget.\n-- Aligned with the Thunder Belt.\n-- Element: Water\n-- Modifiers: STR:60%  VIT:60%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1, 1, 1 }\n    params.str_wsc = 0.32\n    params.vit_wsc = 0.32\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.6\n        params.vit_wsc = 0.6\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.ATTACK_DOWN\n    local actionElement = xi.element.WATER\n    local power         = 25\n    local duration      = math.floor(120 + 6 * tp / 100 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/wheeling_thrust.lua"]={["Path"]="scripts/actions/weaponskills/wheeling_thrust.lua",["SHA256"]="1c40fbb4b446ef4c29ad3eced5939f578ec18b5ee8be904d0b2cdd4001e9826f",["Text"]="-----------------------------------\n-- Wheeling Thrust\n-- Polearm weapon skill\n-- Skill Level: 225\n-- Ignores enemy's defense. Amount ignored varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Flame Gorget & Light Gorget.\n-- Aligned with the Flame Belt & Light Belt.\n-- Element: None\n-- Modifiers: STR:80%\n-- 100%TP    200%TP    300%TP\n-- 1.75      1.75      1.75\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.75, 1.75, 1.75 }\n    params.str_wsc = 0.5\n    -- Defense ignored is 50%, 75%, 100% (50% at 100 TP is accurate, other values are guesses)\n    params.ignoredDefense = { 0.5, 0.75, 1.0 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.8\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/wildfire.lua"]={["Path"]="scripts/actions/weaponskills/wildfire.lua",["SHA256"]="ecb149c5c704c574d7d1addd1fdf2cac4bbcf2353f2bab57fc4db6a0ad4a93f7",["Text"]="-----------------------------------\n-- Wildfire\n-- Skill Level: N/A\n-- Description: Deals fire elemental damage. Enmity generation varies with TP. Armageddon: Aftermath.\n-- Acquired permanently by completing the appropriate Walk of Echoes Weapon Skill Trials.\n-- Can also be used by equipping Armageddon (85)/(90)/(95)/(99) or Bedlam +1/+2/+3.\n-- Aligned with the Soil Gorget & Shadow Gorget.\n-- Aligned with the Soil Belt & Shadow Belt.\n-- Element: Fire\n-- Skillchain Properties: Darkness/Gravitation\n-- Modifiers: AGI:60%\n-- Damage Multipliers by TP:\n--  100%TP    200%TP    300%TP\n--  5.5      5.5     5.5\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 5.5, 5.5, 5.5 }\n    params.agi_wsc = 0.6\n    params.ele = xi.element.FIRE\n    params.skill = xi.skill.MARKSMANSHIP\n    params.includemab = true\n    params.dStat = xi.mod.AGI\n\n    -- TODO: needs to give enmity down at varying tp percent's that is treated separately than the gear cap of -50% enmity http://www.bg-wiki.com/bg/Wildfire\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.RANGED, xi.aftermath.type.EMPYREAN)\n\n    local damage, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n\n    return tpHits, extraHits, false, damage\nend\n\nreturn weaponskillObject\n"}};
